contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 preBalance, uint256 callValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (preBalance)); require(preBalance <= 1000000000000000000000000000000);
        require(preBalance > 0);
        require(address(this).balance >= preBalance);

        // give the caller (this test contract) some credit first
        c.deposit{value: preBalance}(); if (__ESBMC_reverted()) return;

        // now drain all credit by calling withdrawAll once
        c.withdrawAll(); if (__ESBMC_reverted()) return;

        // caller's credit should now be zero; read before-values
        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        // deciding call: caller has no credit, withdrawAll must do nothing
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 cBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;

        assert(!reverted && cBalAfter == cBalBefore && selfBalAfter == selfBalBefore);
    }
}

