// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 preBalance, uint256 callValue) internal {
        preBalance = bound(preBalance, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(preBalance > 0);
        vm.assume(address(this).balance >= preBalance);
        try c.deposit{value: preBalance}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint256 cBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;
        assertTrue(!reverted && cBalAfter == cBalBefore && selfBalAfter == selfBalBefore);
    }

    function testFuzz_run(uint256 preBalance, uint256 callValue) public {
        _run(preBalance, callValue);
    }

    receive() external payable {}
}
